Service tests (use @ExtendWith(MockitoExtension.class)):
```java
@Mock TaskRepository repo;
@InjectMocks TaskService service; // assume constructor injection

@Test
void listTasksForUser_noStatus_callsFindByUserId() {
    Long userId = 42L;
    List<Task> expected = List.of(new Task()); // create a simple Task instance
    when(repo.findByUserId(userId)).thenReturn(expected);

    assertEquals(expected, service.listTasksForUser(userId));
    assertEquals(expected, service.listTasksForUser(userId, Optional.empty()));
    verify(repo, times(2)).findByUserId(userId); // both code paths use repository.findByUserId
    verify(repo, never()).findByUserIdAndStatus(anyLong(), any());
}

@Test
void listTasksForUser_withValidStatus_callsFindByUserIdAndStatus() {
    Long userId = 42L;
    List<Task> expected = List.of(new Task());
    when(repo.findByUserIdAndStatus(userId, TaskStatus.OPEN)).thenReturn(expected);

    List<Task> actual = service.listTasksForUser(userId, Optional.of("OPEN"));
    assertEquals(expected, actual);
    verify(repo).findByUserIdAndStatus(userId, TaskStatus.OPEN);
    verify(repo, never()).findByUserId(userId);
}

@Test
void listTasksForUser_withInvalidStatus_returnsEmptyList() {
    Long userId = 42L;
    List<Task> actual = service.listTasksForUser(userId, Optional.of("NOT_A_REAL_STATUS"));
    assertTrue(actual.isEmpty());
    verify(repo, never()).findByUserId(anyLong());
    verify(repo, never()).findByUserIdAndStatus(anyLong(), any());
}
```

